/**
 * Build an McpServer instance with every tool registered for the given scope.
 *  - scope="read"  → only register read-only tools; writes are hidden from tools/list.
 *  - scope="write" → register every tool (read + write).
 *  - One fresh server per HTTP request (stateless Streamable HTTP; see streamable-http.ts).
 */
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import type { AuthScope } from "../api/env";
import { registerGeneratedOpenApiTools } from "./generated/openapi-tools";

export function createAventureMcpServer(scope: AuthScope): McpServer {
  const server = new McpServer(
    { name: "aventure-mcp-server", title: "aVenture MCP Server", version: "0.1.0" },
    { capabilities: { logging: {} } },
  );
  registerGeneratedOpenApiTools(server, scope);
  return server;
}
