import cors from "cors";
import express, { type NextFunction, type Request, type Response } from "express";
import { rateLimit } from "express-rate-limit";
import { randomUUID } from "node:crypto";
import type { Server } from "node:http";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";
import { logError, logInfo, logWarn } from "../logging";
import { recordHttpRequest, registerMetricsRoute, shutdownMetrics } from "../metrics";
import { createAventureMcpServer } from "./create-server";
import { authFailureDetail, authorize, configuredCredentials } from "./http-auth";
import { jsonBodyLimitGate } from "./json-body-limit";

const HTTP_ERROR_STATUS_MIN = 400;
const BAD_REQUEST_STATUS = 400;
const PAYLOAD_TOO_LARGE_STATUS = 413;
const DEFAULT_JSON_BODY_LIMIT = "10mb";

export interface StartOptions {
  readonly port: number;
  readonly host?: string;
  readonly path: string;
  readonly adminApiKey?: string;
  readonly clientSecret?: string;
  readonly jsonBodyLimit?: string | number;
}

export interface RunningServer {
  readonly server: Server;
  readonly close: () => Promise<void>;
}

export async function startStreamableHttpServer(options: StartOptions): Promise<RunningServer> {
  const creds = configuredCredentials(options);
  const jsonBodyLimit = options.jsonBodyLimit ?? DEFAULT_JSON_BODY_LIMIT;

  const app = express();
  app.set("trust proxy", 1);
  app.use(cors());
  app.use(
    jsonBodyLimitGate({
      path: options.path,
      limit: jsonBodyLimit,
      reject: (res) =>
        sendProblem(
          res,
          PAYLOAD_TOO_LARGE_STATUS,
          "Payload Too Large",
          "Request JSON body exceeds the MCP transport size limit.",
        ),
    }),
  );
  app.use(express.json({ limit: jsonBodyLimit }));
  app.use((req: Request, res: Response, next) => {
    const requestId = randomUUID();
    const started = performance.now();
    const requestFields = {
      requestId,
      method: req.method,
      path: req.path,
      host: req.hostname,
      userAgent: req.get("user-agent"),
    };
    const expectedRobotsProbe = isExpectedRobotsProbe(req);
    if (!expectedRobotsProbe) {
      logInfo({
        component: "aventure-mcp-server",
        event: "http_request",
        fields: requestFields,
      });
    }
    res.on("finish", () => {
      const durationMs = Math.round(performance.now() - started);
      recordHttpRequest(req.method, req.path, res.statusCode, durationMs);
      const write =
        res.statusCode >= HTTP_ERROR_STATUS_MIN && !expectedRobotsProbe ? logWarn : logInfo;
      write({
        component: "aventure-mcp-server",
        event: "http_response",
        fields: {
          ...requestFields,
          status: res.statusCode,
          durationMs,
        },
      });
    });
    next();
  });

  app.get("/health", (...args: [Request, Response]) => {
    const res = args[1];
    res.status(200).json({ status: "UP" });
  });

  registerMetricsRoute(app, creds.clientSecret);

  app.get("/", (...args: [Request, Response]) => {
    const res = args[1];
    res.status(200).json({
      name: "aventure-mcp-server",
      mcp: options.path,
      health: "/health",
      transport: "streamable-http",
      method: "POST",
    });
  });

  app.get("/favicon.ico", (...args: [Request, Response]) => {
    const res = args[1];
    res.status(204).end();
  });

  const mcpLimiter = rateLimit({ windowMs: 60_000, limit: 120 });
  app.post(options.path, mcpLimiter, async (req: Request, res: Response) => {
    const decision = authorize(req, creds);
    if (!decision.ok) {
      logWarn({
        component: "aventure-mcp-server",
        event: "unauthorized_request",
        fields: {
          method: req.method,
          path: req.path,
          reason: decision.reason,
          hasAuthorization: decision.hasAuthorization,
          hasApiKey: decision.hasApiKey,
          hasClientSecret: decision.hasClientSecret,
          configuredAdminApiKey: decision.configuredAdminApiKey,
          configuredClientSecret: decision.configuredClientSecret,
          candidateFingerprint: decision.candidateFingerprint.join(","),
        },
      });
      sendProblem(res, 401, "Unauthorized", authFailureDetail(decision.reason, creds));
      return;
    }
    const accept = req.header("accept") ?? "*/*";
    if (
      !accept.includes("*/*") &&
      (!accept.includes("application/json") || !accept.includes("text/event-stream"))
    ) {
      sendProblem(
        res,
        406,
        "Not Acceptable",
        "MCP Streamable HTTP requires Accept: application/json, text/event-stream.",
      );
      return;
    }
    logInfo({
      component: "aventure-mcp-server",
      event: "mcp_request_authorized",
      fields: { method: req.method, path: req.path, scope: decision.scope },
    });
    const mcp = createAventureMcpServer(decision.scope);
    const transport = new StreamableHTTPServerTransport({
      sessionIdGenerator: undefined,
    });
    res.on("close", () => {
      logCloseFailure(() => transport.close(), "transport_close_failed", req);
      logCloseFailure(() => mcp.close(), "mcp_close_failed", req);
    });
    try {
      await mcp.connect(transport);
      await transport.handleRequest(req, res, req.body);
    } catch (error) {
      logError({
        component: "aventure-mcp-server",
        event: "transport_error",
        message: (error as Error).message,
        fields: { method: req.method, path: req.path },
        error,
      });
      if (!res.headersSent) {
        sendProblem(res, 500, "MCP transport error", (error as Error).message);
      }
    }
  });

  app.all(options.path, (...args: [Request, Response]) => {
    const res = args[1];
    sendProblem(res, 405, "Method Not Allowed", "MCP transport accepts POST requests only.");
  });

  app.use((error: unknown, req: Request, res: Response, next: NextFunction) => {
    if (res.headersSent) {
      next(error);
      return;
    }
    const bodyError = jsonBodyError(error);
    if (bodyError === undefined) {
      next(error);
      return;
    }
    logWarn({
      component: "aventure-mcp-server",
      event: "json_body_rejected",
      message: bodyError.message,
      fields: { method: req.method, path: req.path, status: bodyError.status },
    });
    sendProblem(
      res,
      bodyError.status,
      bodyError.status === PAYLOAD_TOO_LARGE_STATUS ? "Payload Too Large" : "Bad Request",
      bodyError.status === PAYLOAD_TOO_LARGE_STATUS
        ? "Request JSON body exceeds the MCP transport size limit."
        : "Request body must be valid JSON.",
    );
  });

  return await new Promise<RunningServer>((resolve, reject) => {
    let listener: Server;
    const onListening = (): void => {
      resolve({
        server: listener,
        close: async (): Promise<void> => {
          await new Promise<void>((ok, fail) => {
            listener.close((err) => (err ? fail(err) : ok()));
            // Node recommends closing idle sockets after close() when both are used; this keeps
            // ephemeral test servers from leaving fetch-visible keep-alive sockets behind.
            listener.closeIdleConnections();
          });
          await shutdownMetrics();
        },
      });
    };
    listener =
      options.host === undefined
        ? app.listen(options.port, onListening)
        : app.listen(options.port, options.host, onListening);
    listener.on("error", reject);
  });
}

const isExpectedRobotsProbe = (request: Request): boolean =>
  request.method === "GET" && /^\/robots\.txt\/?$/iu.test(request.path);

function sendProblem(res: Response, status: number, title: string, detail: string): void {
  res.status(status).json({ type: "about:blank", title, status, detail });
}

function jsonBodyError(
  error: unknown,
): { readonly status: number; readonly message: string } | undefined {
  if (typeof error !== "object" || error === null || !("type" in error) || !("status" in error))
    return undefined;
  const status =
    error.type === "entity.too.large"
      ? PAYLOAD_TOO_LARGE_STATUS
      : error.type === "entity.parse.failed"
        ? BAD_REQUEST_STATUS
        : error.status === PAYLOAD_TOO_LARGE_STATUS || error.status === BAD_REQUEST_STATUS
          ? error.status
          : undefined;
  return status === undefined
    ? undefined
    : {
        status,
        message:
          "message" in error && typeof error.message === "string"
            ? error.message
            : "JSON body rejected",
      };
}

function logCloseFailure(
  close: () => Promise<void>,
  event: "transport_close_failed" | "mcp_close_failed",
  req: Request,
): void {
  close().catch((error) => {
    logWarn({
      component: "aventure-mcp-server",
      event,
      message: (error as Error).message,
      fields: { method: req.method, path: req.path },
      error,
    });
  });
}
