import { cliShellQuote, flagName, mcpToolForIntent } from "../config/tool-policy";
import type { McpGenerationContract } from "./contract";
import {
  cliBodyParameterInputName,
  cliParameterInputName,
  type McpGenerationParameter,
} from "./contract-parameter";

export type HelpRecommendation = Readonly<
  Record<"intent" | "recommendedCommand" | "useFor" | "notFor" | "apiRoute" | "mcpTool", string>
> & {
  readonly missingInputs: readonly string[];
  readonly pathInput: readonly string[];
  readonly queryInput: readonly string[];
  readonly bodyInput: readonly string[];
  readonly operationDescription: string;
  readonly bodySchemaName: string | null;
  readonly bodyKind: string | null;
  readonly bodyRequired: boolean;
  readonly requiredBodyPath: readonly string[];
  readonly confidence: "high" | "medium" | "low";
  readonly alternatives: readonly string[];
};

export type OperationGuidance = {
  readonly useFor: string;
  readonly notFor: string;
};
export type EnumCommandFlag = {
  readonly inputName: string;
  readonly flag: string;
};

const CONFIDENCE_SCORE = { high: 60, medium: 30 } as const;
const CONFIDENCE_GAP = { high: 20, medium: 10 } as const;

export function toHelpRecommendation(input: {
  readonly contract: McpGenerationContract;
  readonly guidance: OperationGuidance;
  readonly enumQueryFlag: EnumCommandFlag | null;
  readonly confidence: HelpRecommendation["confidence"];
  readonly alternatives: readonly string[];
}): HelpRecommendation {
  const { contract, guidance, enumQueryFlag } = input;
  const enumInputName = enumQueryFlag?.inputName ?? null;
  const requiredParameter = requiredCommandParameter(contract.parameter, enumInputName);
  const requiredBodyParameter = requiredCommandParameter(
    contract.requestBody?.parameter ?? [],
    null,
  );
  const requiredFlags = requiredParameter.map((parameter) => commandFlag(contract, parameter));
  const requiredBodyFlags = requiredBodyParameter.map((parameter) =>
    bodyCommandFlag(contract, parameter),
  );
  const requiredBodyPath = contract.requestBody?.requiredPath ?? [];
  const directBodyPath = new Set((contract.requestBody?.parameter ?? []).map(({ name }) => name));
  const requiredFilePath = requiredBodyPath.filter((path) => !directBodyPath.has(path));
  const needsBodyFile =
    contract.requestBody?.required === true &&
    contract.requestBody.kind === "json" &&
    (requiredBodyFlags.length === 0 || requiredFilePath.length > 0);
  const commandParts = [
    "aventure-cli",
    ...contract.projection.cliPath,
    ...(enumQueryFlag === null ? [] : [enumQueryFlag.flag]),
    ...requiredFlags,
    ...requiredBodyFlags,
    ...(needsBodyFile ? ['--from-file "<path>"'] : []),
    ...(contract.projection.dryRun ? ["--execute"] : []),
  ];
  return {
    intent: contract.intent,
    recommendedCommand: commandParts.join(" "),
    useFor: guidance.useFor,
    notFor: guidance.notFor,
    apiRoute: `${contract.method} ${contract.path}`,
    mcpTool: mcpToolForIntent(contract.intent),
    missingInputs: [
      // Query/path keys an MCP caller must pass VERBATIM to aventure_read/write: the API wire param
      // name (`id`/`slug`), not the CLI rename (`mediaId`/`entitySlug`) which lives in recommendedCommand.
      ...requiredParameter.map((parameter) => parameter.name),
      ...requiredBodyParameter.map((parameter) => cliBodyParameterInputName(contract, parameter)),
      ...requiredFilePath,
      ...(needsBodyFile ? ["fromFile"] : []),
    ],
    pathInput: inputNameForLocation(contract.parameter, "path"),
    queryInput: inputNameForLocation(contract.parameter, "query"),
    bodyInput: (contract.requestBody?.parameter ?? []).map((parameter) => parameter.name),
    operationDescription: contract.description,
    bodySchemaName: contract.requestBody?.schemaName ?? null,
    bodyKind: contract.requestBody?.kind ?? null,
    bodyRequired: contract.requestBody?.required ?? false,
    requiredBodyPath,
    confidence: input.confidence,
    alternatives: input.alternatives,
  };
}

export function guidanceFromContract(contract: McpGenerationContract): OperationGuidance {
  const sections = descriptionGuidance(contract.description);
  return {
    useFor:
      sections.useFor ||
      contract.summary ||
      contract.description ||
      `${contract.method} ${contract.path}`,
    notFor: sections.notFor || "See operation description",
  };
}

export function descriptionGuidance(description: string): OperationGuidance {
  const useForMatch = description.match(/USE FOR:\s*([\s\S]*?)(?:NOT FOR:|$)/iu);
  const notForMatch = description.match(/NOT FOR:\s*([\s\S]*?)$/iu);
  return {
    useFor: useForMatch?.[1]?.trim() ?? "",
    notFor: notForMatch?.[1]?.trim() ?? "",
  };
}

export function confidenceFromScores(
  bestScore: number,
  secondScore: number,
): HelpRecommendation["confidence"] {
  if (bestScore === 0) return "low";
  const gap = bestScore - secondScore;
  if (bestScore >= CONFIDENCE_SCORE.high && gap >= CONFIDENCE_GAP.high) return "high";
  if (bestScore >= CONFIDENCE_SCORE.medium && gap >= CONFIDENCE_GAP.medium) return "medium";
  return "low";
}

export function unknownHelpRecommendation(
  useFor: string,
  notFor: string,
  missingInputs: readonly string[] = [],
): HelpRecommendation {
  return {
    intent: "unknown",
    recommendedCommand: "",
    useFor,
    notFor,
    apiRoute: "",
    mcpTool: "",
    missingInputs,
    pathInput: [],
    queryInput: [],
    bodyInput: [],
    operationDescription: "",
    bodySchemaName: null,
    bodyKind: null,
    bodyRequired: false,
    requiredBodyPath: [],
    confidence: "low",
    alternatives: [],
  };
}

function inputNameForLocation(
  parameters: readonly McpGenerationParameter[],
  location: "path" | "query",
): readonly string[] {
  return parameters.flatMap((parameter) =>
    parameter.in === location
      ? (parameter.itemProperty ?? [parameter]).map((item) => item.name)
      : [],
  );
}

function requiredCommandParameter(
  parameters: readonly McpGenerationParameter[],
  enumInputName: string | null,
): readonly McpGenerationParameter[] {
  return parameters.filter(
    (parameter) =>
      parameter.required &&
      parameter.schemaDefault === undefined &&
      (enumInputName === null || parameter.inputName !== enumInputName),
  );
}

function commandFlag(contract: McpGenerationContract, parameter: McpGenerationParameter): string {
  const inputName = cliParameterInputName(contract, parameter);
  const placeholder = `${inputName}${parameter.schemaType === "array" ? "..." : ""}`;
  return `${flagName(inputName)} ${cliShellQuote(`<${placeholder}>`)}`;
}

function bodyCommandFlag(
  contract: McpGenerationContract,
  parameter: McpGenerationParameter,
): string {
  const inputName = cliBodyParameterInputName(contract, parameter);
  const placeholder = `${inputName}${parameter.schemaType === "array" ? "..." : ""}`;
  return `${flagName(inputName)} ${cliShellQuote(`<${placeholder}>`)}`;
}
