#!/usr/bin/env node
/**
 * aventure-mcp-server entrypoint.
 *  - AVENTURE_MCP_PORT (default 3333), AVENTURE_MCP_PATH (default /mcp),
 *    and AVENTURE_MCP_JSON_LIMIT (default 10mb) control binding/body parsing.
 *  - Logs a single listening line to stdout; agent configs point at http://host:port/mcp.
 */
import { materializeAuth } from "../api/auth-resolver";
import { describeError, logError, logInfo, shutdownLogging } from "../logging";
import { startStreamableHttpServer } from "./streamable-http";

const MAX_PORT = 65535;
const FORCE_EXIT_MS = 55_000;

await materializeAuth();

const port = readPort();
const path = process.env.AVENTURE_MCP_PATH ?? "/mcp";
const jsonBodyLimit = process.env.AVENTURE_MCP_JSON_LIMIT ?? "10mb";
const adminApiKey = process.env.ADMIN_API_KEY || undefined;
const clientSecret = process.env.CLIENT_SECRET || undefined;

let isShuttingDown = false;

function shutdownLoggingThenExit(exitCode: number): void {
  shutdownLogging()
    .catch((error: unknown) => {
      const safeMessage = describeError(error);
      process.stderr.write(`aventure-mcp-server logging shutdown failed: ${safeMessage}\n`);
    })
    .finally(() => process.exit(exitCode));
}

startStreamableHttpServer({ port, path, jsonBodyLimit, adminApiKey, clientSecret }).then(
  (runningServer) => {
    logInfo({
      component: "aventure-mcp-server",
      event: "server_listening",
      fields: { port, path },
    });
    process.stdout.write(`aventure-mcp-server listening at http://localhost:${port}${path}\n`);

    const shutdown = (signal: NodeJS.Signals): void => {
      if (isShuttingDown) {
        return;
      }
      isShuttingDown = true;

      logInfo({
        component: "aventure-mcp-server",
        event: "server_shutdown_started",
        fields: { signal },
      });

      const forceExit = setTimeout(() => {
        logError({
          component: "aventure-mcp-server",
          event: "server_shutdown_timeout",
          message: "MCP server did not drain before Railway SIGKILL window",
          fields: { signal, forceExitMs: FORCE_EXIT_MS },
        });
        shutdownLoggingThenExit(1);
      }, FORCE_EXIT_MS);
      forceExit.unref();

      runningServer
        .close()
        .then(() => {
          clearTimeout(forceExit);
          logInfo({
            component: "aventure-mcp-server",
            event: "server_shutdown_completed",
            fields: { signal },
          });
          return shutdownLogging();
        })
        .then(() => {
          process.exit(0);
        })
        .catch((error: unknown) => {
          const safeMessage = describeError(error);
          clearTimeout(forceExit);
          logError({
            component: "aventure-mcp-server",
            event: "server_shutdown_failed",
            message: safeMessage,
            fields: { signal },
            error,
          });
          shutdownLoggingThenExit(1);
        });
    };

    for (const signal of ["SIGTERM", "SIGINT"] as const) {
      process.on(signal, shutdown);
    }
  },
  async (error: unknown) => {
    const safeMessage = describeError(error);
    logError({
      component: "aventure-mcp-server",
      event: "server_start_failed",
      message: safeMessage,
      error,
    });
    process.stderr.write(`aventure-mcp-server failed to start: ${safeMessage}\n`);
    await shutdownLogging();
    process.exit(1);
  },
);

function readPort(): number {
  const rawPort = process.env.AVENTURE_MCP_PORT ?? process.env.PORT ?? "3333";
  const parsed = Number(rawPort);
  if (!Number.isInteger(parsed) || parsed < 1 || parsed > MAX_PORT) {
    throw new Error(`Invalid MCP server port: ${rawPort}`);
  }
  return parsed;
}
