import type { NextFunction, Request, Response } from "express";

const BYTES_PER_KIBIBYTE = 1024;
const BYTES_PER_MEBIBYTE = BYTES_PER_KIBIBYTE * BYTES_PER_KIBIBYTE;
const BODY_LIMIT_SIZE_MATCH_INDEX = 1;
const BODY_LIMIT_UNIT_MATCH_INDEX = 2;
const BYTE_UNIT = "b";
const KIBIBYTE_UNIT = "kb";
const MEBIBYTE_UNIT = "mb";
const BODY_LIMIT_PATTERN = /^(\d+(?:\.\d+)?)\s*(b|kb|mb)?$/u;

interface JsonBodyLimitGateOptions {
  readonly path: string;
  readonly limit: string | number;
  readonly reject: (res: Response) => void;
}

export function jsonBodyLimitGate(
  options: JsonBodyLimitGateOptions,
): (req: Request, res: Response, next: NextFunction) => void {
  const maxBodyByteSize = jsonBodyLimitByteSize(options.limit);
  const configuredPath = normalizedRoutePath(options.path);
  return (req: Request, res: Response, next: NextFunction): void => {
    if (
      maxBodyByteSize === undefined ||
      req.method !== "POST" ||
      normalizedRoutePath(req.path) !== configuredPath
    ) {
      next();
      return;
    }
    const bodyByteSize = requestContentLengthByteSize(req.header("content-length"));
    if (bodyByteSize === undefined || bodyByteSize <= maxBodyByteSize) {
      next();
      return;
    }
    res.setHeader("Connection", "close");
    options.reject(res);
  };
}

function normalizedRoutePath(path: string): string {
  const normalized = path.endsWith("/") ? path.slice(0, -1) : path;
  return normalized === "" ? "/" : normalized;
}

function jsonBodyLimitByteSize(limit: string | number): number | undefined {
  if (typeof limit === "number") {
    return Number.isFinite(limit) && limit >= 0 ? limit : undefined;
  }
  const bodyLimitMatch = BODY_LIMIT_PATTERN.exec(limit.trim().toLowerCase());
  if (bodyLimitMatch === null) {
    return undefined;
  }
  const bodyLimitSize = Number(bodyLimitMatch[BODY_LIMIT_SIZE_MATCH_INDEX]);
  if (!Number.isFinite(bodyLimitSize)) {
    return undefined;
  }
  switch (bodyLimitMatch[BODY_LIMIT_UNIT_MATCH_INDEX] ?? BYTE_UNIT) {
    case MEBIBYTE_UNIT:
      return Math.floor(bodyLimitSize * BYTES_PER_MEBIBYTE);
    case KIBIBYTE_UNIT:
      return Math.floor(bodyLimitSize * BYTES_PER_KIBIBYTE);
    case BYTE_UNIT:
      return Math.floor(bodyLimitSize);
  }
  return undefined;
}

function requestContentLengthByteSize(rawContentLength: string | undefined): number | undefined {
  if (rawContentLength === undefined) {
    return undefined;
  }
  const contentLengthByteSize = Number(rawContentLength);
  return Number.isInteger(contentLengthByteSize) && contentLengthByteSize >= 0
    ? contentLengthByteSize
    : undefined;
}
