import { metrics, type Histogram, type Meter } from "@opentelemetry/api";
import { PrometheusExporter } from "@opentelemetry/exporter-prometheus";
import { HostMetrics } from "@opentelemetry/host-metrics";
import { resourceFromAttributes } from "@opentelemetry/resources";
import { MeterProvider } from "@opentelemetry/sdk-metrics";
import { createHash, timingSafeEqual } from "node:crypto";
import type { Application, NextFunction, Request, Response } from "express";
import { parseBearerToken } from "./http-credentials";
import { otelResourceAttributes } from "./logging";

/**
 * Prometheus-scrape metrics for the MCP server.
 *  - Mirrors back-end /actuator/prometheus auth (Bearer CLIENT_SECRET) so the same
 *    grafana-config's inline prometheus_yml scrape job pattern applies.
 *  - HTTP histogram + host metrics by default. No env-var feature flag; presence of
 *    CLIENT_SECRET is the natural enable condition (also the scrape auth credential).
 */

const METER_NAME = "aventure-mcp-server";
const HTTP_REQUEST_HISTOGRAM_NAME = "http_server_requests_seconds";
const HTTP_BUCKET_BOUNDARIES = [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10];

let prometheusExporter: PrometheusExporter | undefined;
let meterProviderInstance: MeterProvider | undefined;
let meterInstance: Meter | undefined;
let httpRequestHistogram: Histogram | undefined;
let metricsEnabled = false;
// Held so the HostMetrics observable callbacks aren't GC'd while the provider is alive.
let hostMetricsInstance: HostMetrics | undefined;

function ensureMeterProvider(): { provider: MeterProvider; exporter: PrometheusExporter } {
  if (meterProviderInstance !== undefined && prometheusExporter !== undefined) {
    return { provider: meterProviderInstance, exporter: prometheusExporter };
  }
  const exporter = new PrometheusExporter({ preventServerStart: true });
  const provider = new MeterProvider({
    resource: resourceFromAttributes(otelResourceAttributes()),
    readers: [exporter],
  });
  metrics.setGlobalMeterProvider(provider);
  meterProviderInstance = provider;
  prometheusExporter = exporter;

  const hostMetrics = new HostMetrics({ meterProvider: provider, name: METER_NAME });
  hostMetrics.start();
  hostMetricsInstance = hostMetrics;
  return { provider, exporter };
}

function meter(): Meter {
  if (meterInstance !== undefined) return meterInstance;
  meterInstance = ensureMeterProvider().provider.getMeter(METER_NAME);
  return meterInstance;
}

export function recordHttpRequest(
  method: string,
  route: string,
  status: number,
  durationMs: number,
): void {
  if (!metricsEnabled) return;
  if (httpRequestHistogram === undefined) {
    httpRequestHistogram = meter().createHistogram(HTTP_REQUEST_HISTOGRAM_NAME, {
      description: "HTTP server request latency in seconds, partitioned by method/route/status.",
      unit: "s",
      advice: { explicitBucketBoundaries: HTTP_BUCKET_BOUNDARIES },
    });
  }
  httpRequestHistogram.record(durationMs / 1000, {
    method: method.toUpperCase(),
    route,
    status: String(status),
  });
}

export function registerMetricsRoute(app: Application, clientSecret: string | undefined): void {
  if (clientSecret === undefined || clientSecret.length === 0) return;
  metricsEnabled = true;
  const { exporter } = ensureMeterProvider();
  const expectedHash = createHash("sha256").update(clientSecret).digest();

  app.get(
    "/metrics",
    (req: Request, res: Response, next: NextFunction) => {
      if (!matchesBearer(req.headers.authorization, expectedHash)) {
        res.status(401).type("text/plain").send("Unauthorized");
        return;
      }
      next();
    },
    (req: Request, res: Response) => {
      exporter.getMetricsRequestHandler(req, res);
    },
  );
}

export async function shutdownMetrics(): Promise<void> {
  const provider = meterProviderInstance;
  if (hostMetricsInstance !== undefined) {
    hostMetricsInstance = undefined;
  }
  meterProviderInstance = undefined;
  prometheusExporter = undefined;
  meterInstance = undefined;
  httpRequestHistogram = undefined;
  metricsEnabled = false;
  if (provider !== undefined) await provider.shutdown();
}

function matchesBearer(header: string | undefined, expectedHash: Buffer): boolean {
  const presented = parseBearerToken(header);
  if (presented === undefined) return false;
  const presentedHash = createHash("sha256").update(presented).digest();
  if (presentedHash.length !== expectedHash.length) return false;
  return timingSafeEqual(presentedHash, expectedHash);
}
