import { flagName } from "../config/tool-policy";
import type { McpGenerationContract } from "./contract";
import {
  cliBodyParameterInputName,
  cliParameterInputName,
  type McpGenerationParameter,
} from "./contract-parameter";

type HelpArgument = {
  readonly name: string;
  readonly flag: string;
  readonly required: boolean;
  readonly location: McpGenerationParameter["in"];
  readonly description: string;
};

export function argumentGroups(contract: McpGenerationContract) {
  const queryAndPath = contract.parameter.map((parameter) =>
    helpArgument(parameter, cliParameterInputName(contract, parameter)),
  );
  const body = (contract.requestBody?.parameter ?? []).map((parameter) =>
    helpArgument(parameter, cliBodyParameterInputName(contract, parameter)),
  );
  return {
    selector: queryAndPath.filter((argument) => argument.location === "path" || selector(argument)),
    pagination: queryAndPath.filter(paginationArgument),
    filter: [...queryAndPath.filter(filterArgument), ...body.filter(filterArgument)],
    body: body.filter((argument) => !filterArgument(argument)),
  };
}

function helpArgument(parameter: McpGenerationParameter, inputName: string): HelpArgument {
  // MCP callers pass query/path keys VERBATIM to the API (openapi-call `withSearchParams` / path
  // template), so the MCP-facing `name` MUST be the API wire param name: e.g. `id`/`slug`, not the
  // CLI-ergonomic rename `mediaId`/`entitySlug` (which only ever rewrites a bare `id`/`slug`). Passing
  // the renamed key returns 422 unknown-parameter. The rename stays on `flag` for the CLI surface.
  // Body keys keep the input name (the JSON body shape the caller assembles).
  return {
    name: parameter.in === "body" ? inputName : parameter.name,
    flag: flagName(inputName),
    required: parameter.required,
    location: parameter.in,
    description: parameter.description || `${parameter.name} ${parameter.in} parameter`,
  };
}

function selector(argument: HelpArgument): boolean {
  return /(^|[A-Z])(id|slug)$/u.test(argument.name);
}

function paginationArgument(argument: HelpArgument): boolean {
  return ["page", "size", "sort", "cursor", "mode", "projection"].includes(argument.name);
}

function filterArgument(argument: HelpArgument): boolean {
  return argument.location !== "path" && !selector(argument) && !paginationArgument(argument);
}
