const BEARER_PREFIX = "bearer ";
const MAX_AUTHORIZATION_HEADER_LENGTH = 4096;

export function parseBearerToken(authorization: string | undefined): string | undefined {
  if (authorization === undefined || authorization.length > MAX_AUTHORIZATION_HEADER_LENGTH) {
    return undefined;
  }
  if (authorization.slice(0, BEARER_PREFIX.length).toLowerCase() !== BEARER_PREFIX) {
    return undefined;
  }
  const token = authorization.slice(BEARER_PREFIX.length).trim();
  return token.length > 0 ? token : undefined;
}
