import type { Request } from "express";
import { createHash, timingSafeEqual } from "node:crypto";
import type { AuthScope } from "../api/env";
import { parseBearerToken } from "../http-credentials";

interface CredentialOptions {
  readonly adminApiKey?: string;
  readonly clientSecret?: string;
}

export interface ConfiguredCredentials {
  readonly adminApiKey?: string;
  readonly clientSecret?: string;
}

interface AuthorizedRequest {
  readonly ok: true;
  readonly scope: AuthScope;
}

export interface UnauthorizedRequest {
  readonly ok: false;
  readonly reason: "missing_credential" | "credential_mismatch";
  readonly hasAuthorization: boolean;
  readonly hasApiKey: boolean;
  readonly hasClientSecret: boolean;
  readonly configuredAdminApiKey: boolean;
  readonly configuredClientSecret: boolean;
  readonly candidateFingerprint: readonly string[];
}

export type AuthDecision = AuthorizedRequest | UnauthorizedRequest;

export function configuredCredentials(options: CredentialOptions): ConfiguredCredentials {
  const adminApiKey = options.adminApiKey?.trim() || undefined;
  const clientSecret = options.clientSecret?.trim() || undefined;
  if (adminApiKey === undefined && clientSecret === undefined)
    throw new Error(
      "MCP transport requires ADMIN_API_KEY or CLIENT_SECRET to be configured; " +
        "refusing to start an unauthenticated /mcp endpoint.",
    );
  if (adminApiKey !== undefined && adminApiKey === clientSecret)
    throw new Error("ADMIN_API_KEY and CLIENT_SECRET must be distinct values.");
  return { adminApiKey, clientSecret };
}

export function authorize(req: Request, creds: ConfiguredCredentials): AuthDecision {
  const authorization = req.header("authorization");
  const bearer = parseBearerToken(authorization);
  const apiKey = req.header("x-api-key");
  const clientSecret = req.header("x-client-secret");

  for (const [candidate, expected, scope] of [
    [apiKey, creds.adminApiKey, "write"],
    [bearer, creds.adminApiKey, "write"],
    [clientSecret, creds.clientSecret, "read"],
    [bearer, creds.clientSecret, "read"],
  ] as const) {
    if (candidate !== undefined && expected !== undefined && secretEquals(candidate, expected)) {
      return { ok: true, scope };
    }
  }

  const hasCredential = apiKey !== undefined || clientSecret !== undefined || bearer !== undefined;
  return {
    ok: false,
    reason: hasCredential ? "credential_mismatch" : "missing_credential",
    hasAuthorization: authorization !== undefined,
    hasApiKey: apiKey !== undefined,
    hasClientSecret: clientSecret !== undefined,
    configuredAdminApiKey: creds.adminApiKey !== undefined,
    configuredClientSecret: creds.clientSecret !== undefined,
    candidateFingerprint: fingerprints([apiKey, clientSecret, bearer]),
  };
}

export function authFailureDetail(
  reason: UnauthorizedRequest["reason"],
  creds: ConfiguredCredentials,
): string {
  const headers = [
    creds.adminApiKey === undefined
      ? undefined
      : "X-API-Key: <ADMIN_API_KEY> (or Authorization: Bearer <ADMIN_API_KEY>)",
    creds.clientSecret === undefined
      ? undefined
      : "X-Client-Secret: <CLIENT_SECRET> (or Authorization: Bearer <CLIENT_SECRET>)",
  ]
    .filter((header): header is string => header !== undefined)
    .join(" or ");
  if (reason === "missing_credential") {
    return `Provide ${headers}.`;
  }
  return (
    "Supplied MCP transport credential did not match this server's configured " +
    `Doppler secret. Provide the actual secret value via ${headers}; ` +
    "placeholders are rejected."
  );
}

function secretEquals(candidate: string, expected: string): boolean {
  const candidateBytes = Buffer.from(candidate);
  const expectedBytes = Buffer.from(expected);
  return (
    candidateBytes.length === expectedBytes.length && timingSafeEqual(candidateBytes, expectedBytes)
  );
}

function fingerprints(values: readonly (string | undefined)[]): readonly string[] {
  return values
    .filter((credential): credential is string => credential !== undefined)
    .map((credential) => createHash("sha256").update(credential).digest("hex").slice(0, 12));
}
