import type { AventureMethod } from "../api/client";
import { cliShellQuote, flagName } from "../config/tool-policy";
import type { McpGenerationContract } from "./contract";
import { cliParameterInputName, type McpGenerationParameter } from "./contract-parameter";
import { argumentGroups } from "./help-arguments";
import {
  confidenceFromScores,
  descriptionGuidance,
  guidanceFromContract,
  toHelpRecommendation,
  unknownHelpRecommendation,
  type EnumCommandFlag,
  type HelpRecommendation,
} from "./help-recommendation";
import {
  addWithInflections,
  coversEveryQueryTerm,
  expandedTokens,
  meaningfulTokens,
  normalize,
  queryMutationIntent,
  queryTermForms,
} from "./help-token";

export type HelpInput = {
  readonly q?: string;
  readonly root?: string;
  readonly method?: AventureMethod;
  readonly scope?: "read" | "write";
  readonly limit?: number;
  readonly resolve?: boolean;
};

const DEFAULT_HELP_LIMIT = 20;
const CLI_SEGMENT_MATCH_SCORE = 15;

type HelpCounts = Record<"totalOperations" | "matched" | "returned", number>;
type HelpOutput<TSummary extends string, TData> = {
  readonly summary: TSummary;
  readonly data: TData;
  readonly counts: HelpCounts;
};
type HelpResult =
  | HelpOutput<"Operation catalog matches", readonly ReturnType<typeof toCatalogRow>[]>
  | HelpOutput<"How-to command recommendation", HelpRecommendation>;

export function resolveHelpData(
  input: HelpInput,
  contracts: readonly McpGenerationContract[],
): HelpResult {
  const query = input.q?.trim() ?? "";
  const normalizedQuery = normalize(query);
  const tokens = expandedTokens(normalizedQuery);
  const termForm = queryTermForms(normalizedQuery);
  const scoredMatches = contracts
    .filter((contract) => matchesFilters(input, contract))
    .map((contract) => ({
      contract,
      command: contract.projection.cliPath.join(" "),
      score:
        normalizedQuery.length === 0
          ? 1
          : scoreContract(normalizedQuery, tokens, termForm, contract),
    }))
    .filter(({ score }) => normalizedQuery.length === 0 || score > 0);
  const matched = scoredMatches.map(({ contract }) => contract);
  const requestedLimit =
    input.limit === undefined || !Number.isFinite(input.limit) ? DEFAULT_HELP_LIMIT : input.limit;
  const limit = Math.min(matched.length, Math.max(0, Math.trunc(requestedLimit)));
  if (input.resolve !== true) {
    const rankedMatches =
      normalizedQuery.length === 0
        ? scoredMatches
        : scoredMatches.toSorted(
            (left, right) =>
              right.score - left.score ||
              left.command.localeCompare(right.command) ||
              left.contract.operationId.localeCompare(right.contract.operationId),
          );
    const catalog = rankedMatches.slice(0, limit).map(({ contract }) => toCatalogRow(contract));
    return {
      summary: "Operation catalog matches",
      data: catalog,
      counts: {
        totalOperations: contracts.length,
        matched: matched.length,
        returned: catalog.length,
      },
    };
  }
  if (query.length === 0) {
    return unknownResult(
      contracts.length,
      matched.length,
      "Provide q to get a generated command recommendation",
      "Catalog listing; omit resolve to browse operations",
      ["q"],
    );
  }
  const queryIntent = queryMutationIntent(tokens);
  const candidates = scoredMatches.filter(({ contract }) => {
    if (queryIntent === "delete") return true;
    if (contract.intent === "delete" || contract.projection.destructive) return false;
    return queryIntent !== "read" || contract.projection.scope !== "write";
  });
  const scored = candidates.toSorted(
    (a, b) =>
      b.score - a.score ||
      Number(a.contract.projection.scope === "write") -
        Number(b.contract.projection.scope === "write") ||
      a.contract.path.length - b.contract.path.length ||
      a.contract.operationId.localeCompare(b.contract.operationId),
  );
  const best = scored[0];
  if (best === undefined) {
    return unknownResult(
      contracts.length,
      matched.length,
      "No generated operation matched this query",
      "See generated operation descriptions",
    );
  }
  const alternatives = scored
    .slice(1)
    .map(({ contract }) => `aventure-cli ${contract.projection.cliPath.join(" ")}`)
    .filter((command, index, all) => all.indexOf(command) === index)
    .slice(0, 2);
  const contract = best.contract;
  return {
    summary: "How-to command recommendation",
    data: toHelpRecommendation({
      contract,
      guidance: guidanceFromContract(contract),
      confidence: confidenceFromScores(best.score, scored[1]?.score ?? 0),
      alternatives,
      enumQueryFlag: toEnumQueryFlag(tokens, contract),
    }),
    counts: { totalOperations: contracts.length, matched: matched.length, returned: 1 },
  };
}

function unknownResult(
  totalOperations: number,
  matched: number,
  useFor: string,
  notFor: string,
  missingInputs: readonly string[] = [],
): HelpResult {
  return {
    summary: "How-to command recommendation",
    data: unknownHelpRecommendation(useFor, notFor, missingInputs),
    counts: { totalOperations, matched, returned: 0 },
  };
}

function matchesFilters(input: HelpInput, contract: McpGenerationContract): boolean {
  const root = input.root?.trim().toLowerCase();
  if (input.method !== undefined && contract.method !== input.method) return false;
  if (input.scope !== undefined && contract.projection.scope !== input.scope) return false;
  if (root && contract.resource !== root && contract.projection.cliPath[0] !== root) return false;
  return true;
}

function toCatalogRow(contract: McpGenerationContract) {
  return {
    operationId: contract.operationId,
    method: contract.method,
    path: contract.path,
    cli: contract.projection.cliPath.join(" "),
    resource: contract.resource,
    intent: contract.intent,
    scope: contract.projection.scope,
    bodySchemaName: contract.requestBody?.schemaName ?? null,
    bodyKind: contract.requestBody?.kind ?? null,
    bodyRequired: contract.requestBody?.required ?? false,
    requiredBodyPath: contract.requestBody?.requiredPath ?? [],
    argument: argumentGroups(contract),
  };
}

function scoreContract(
  normalizedQuery: string,
  tokens: ReadonlySet<string>,
  termForm: readonly ReadonlySet<string>[],
  contract: McpGenerationContract,
): number {
  if (normalizedQuery.length === 0) return 0;
  const corpus = buildCorpus(contract);
  const identityCorpus = buildIdentityCorpus(contract);
  let score = 0;
  if (corpus.some((value) => value === normalizedQuery)) score += 100;
  if (corpus.some((value) => value.includes(normalizedQuery))) score += 40;
  score += scorePhraseMatches(normalizedQuery, corpus);
  for (const token of tokens) {
    if (corpus.some((value) => value === token)) score += 20;
    else if (corpus.some((value) => value.includes(token))) score += 8;
  }
  for (const segment of contract.projection.cliPath) {
    const segmentForms = new Set<string>();
    addWithInflections(segmentForms, segment);
    if ([...segmentForms].some((form) => tokens.has(form))) score += CLI_SEGMENT_MATCH_SCORE;
  }
  if (coversEveryQueryTerm(termForm, identityCorpus)) score += 200;
  score += scoreEnumParameterMatches(tokens, contract.parameter);
  if (
    ["list", "search", "find", "browse"].some((value) => tokens.has(value)) &&
    contract.operationId.startsWith("list")
  )
    score += 30;
  score -= scoreDescriptionNotFor(normalizedQuery, tokens, contract.description);
  return score;
}

function buildIdentityCorpus(contract: McpGenerationContract): readonly string[] {
  return [contract.operationId, contract.projection.cliPath.join(" "), contract.summary]
    .map(normalize)
    .filter((value) => value.length > 0);
}

function scorePhraseMatches(normalizedQuery: string, corpus: readonly string[]): number {
  const tokens = meaningfulTokens(normalizedQuery);
  let score = 0;
  for (let index = 0; index < tokens.length - 1; index += 1) {
    const phrase = tokens.slice(index, index + 2).join(" ");
    if (corpus.some((value) => value.includes(phrase))) score += 24;
  }
  return score;
}

function buildCorpus(contract: McpGenerationContract): readonly string[] {
  // Enum values are scored once by scoreEnumParameterMatches; repeating them here
  // double-counts generic values like mediaType ENTITY/NEWS and lets them outrank
  // operations whose own name/path matches the query.
  const values = new Set(
    [
      contract.operationId,
      contract.method,
      contract.path,
      contract.resource,
      contract.intent,
      contract.projection.cliPath.join(" "),
      contract.summary,
      descriptionGuidance(contract.description).useFor || contract.description,
    ]
      .map(normalize)
      .filter((value) => value.length > 0),
  );
  return [...values];
}

function scoreDescriptionNotFor(
  normalizedQuery: string,
  tokens: ReadonlySet<string>,
  description: string,
): number {
  const notFor = normalize(descriptionGuidance(description).notFor);
  if (notFor.length === 0) return 0;
  let score = notFor.includes(normalizedQuery) ? 40 : 0;
  for (const token of tokens) {
    if (notFor === token) score += 20;
    else if (notFor.includes(token)) score += 8;
  }
  return score;
}

function toEnumQueryFlag(
  tokens: ReadonlySet<string>,
  contract: McpGenerationContract,
): EnumCommandFlag | null {
  for (const parameter of contract.parameter) {
    if (parameter.in !== "query") continue;
    const matched = enumParameterMatch(tokens, parameter);
    if (matched !== null) {
      const inputName = cliParameterInputName(contract, parameter);
      return {
        inputName: parameter.inputName,
        flag: `${flagName(inputName)} ${cliShellQuote(
          matched,
          parameter.schemaType,
          parameter.itemSchemaType,
        )}`,
      };
    }
  }
  return null;
}

function enumParameterMatch(
  tokens: ReadonlySet<string>,
  parameter: McpGenerationParameter,
): string | null {
  const values = parameter.itemSchemaEnum ?? parameter.schemaEnum ?? [];
  return values.find((value) => enumValueMatches(tokens, value)) ?? null;
}

function scoreEnumParameterMatches(
  tokens: ReadonlySet<string>,
  parameters: readonly McpGenerationParameter[],
): number {
  let score = 0;
  for (const parameter of parameters) {
    const matched = enumParameterMatch(tokens, parameter);
    if (matched === null) continue;
    // Below a multi-token cli-path match: enum values like mediaType ENTITY/NEWS reuse
    // domain nouns, so an enum hit alone must not outrank the owning domain's operations.
    score += parameter.name === parameter.inputName ? 40 : 10;
  }
  return score;
}

function enumValueMatches(tokens: ReadonlySet<string>, value: string): boolean {
  const valueTokens = meaningfulTokens(value);
  return valueTokens.length > 0 && valueTokens.every((token) => tokens.has(token));
}
