/**
 * MCP server CLI runner — single owner for the spawn → parse → tool-result path.
 *
 *  - spawnAventureCli(): bounded subprocess invocation; never throws.
 *  - runCliJson() / runCliJsonWithBody(): always append --json, parse last
 *    stdout line into a result envelope, fall back to a typed failure envelope
 *    when stdout is empty or unparseable.
 *  - analyzeCliError(): map stderr substrings to short, agent-actionable warnings.
 *  - toCallToolResult(): convert a result envelope into the MCP CallToolResult
 *    wire shape with a 50KB structured cap and isError set from envelope.ok.
 *
 * Single owner per [SS1l] / [CC1b] / [LOC-CUT-13].
 */
import type { CallToolResult } from "@modelcontextprotocol/sdk/types.js";
import { execa } from "execa";
import { describeError, logWarn } from "../logging";
import {
  capEnvelope,
  failure,
  parseResultEnvelope,
  type ResultEnvelope,
} from "../api/result-envelope";
import { asCliResponseText } from "../api/text-response";

export interface CliSpawnResult {
  readonly stdout: string;
  readonly stderr: string;
  readonly exitCode: number;
}

/**
 * Hard cap on subprocess stdout. Generous over the 50KB envelope cap
 * (RESULT_ENVELOPE_BYTE_CAP in mcp/api/result-envelope.ts) — protects V8's
 * ~512MB string limit and keeps Railway container memory predictable.
 * Legitimate large outputs (e.g. list-classification-catalog ~5MB raw)
 * are envelope-truncated long before they reach this cap.
 */
export const STDOUT_CAP_BYTES = 32 * 1024 * 1024;

export async function spawnAventureCli(
  args: readonly string[],
  options: {
    readonly cwd?: string;
    readonly env?: Record<string, string | undefined>;
    readonly binary?: string;
    readonly stdin?: string;
  } = {},
): Promise<CliSpawnResult> {
  const binary = options.binary ?? process.env.AVENTURE_CLI_BIN ?? "aventure-cli";
  const result = await execa(binary, [...args, "--json"], {
    cwd: options.cwd,
    env: { ...process.env, ...options.env },
    reject: false,
    input: options.stdin,
    maxBuffer: STDOUT_CAP_BYTES,
  });

  if (result.isMaxBuffer) {
    const envelope: ResultEnvelope<null> = {
      ...failure(`aventure-cli stdout exceeded ${STDOUT_CAP_BYTES} bytes`, [
        "stdout-buffer-overrun",
      ]),
      counts: { capBytes: STDOUT_CAP_BYTES, exitCode: result.exitCode ?? 1 },
    };
    return {
      stdout: `${JSON.stringify(envelope)}\n`,
      stderr: result.stderr ?? "",
      exitCode: 1,
    };
  }

  const fallbackError =
    "shortMessage" in result && typeof result.shortMessage === "string" ? result.shortMessage : "";
  return {
    stdout: result.stdout ?? "",
    stderr: result.stderr || fallbackError,
    exitCode: result.exitCode ?? (result.failed ? 1 : 0),
  };
}

export async function runCliJson(
  args: readonly string[],
  options: { readonly stdin?: string } = {},
): Promise<ResultEnvelope<unknown>> {
  const result = await spawnAventureCli(args, { stdin: options.stdin });
  return parseCliJsonResult(result, args);
}

/** Run a CLI subcommand with optional JSON stdin and execute toggle. */
export async function runCliJsonWithBody(
  args: readonly string[],
  body: unknown,
  execute: boolean,
): Promise<ResultEnvelope<unknown>> {
  const finalArgs = [...args];
  if (execute) finalArgs.push("--execute");
  return await runCliJson(finalArgs, {
    stdin: body === undefined ? undefined : JSON.stringify(body),
  });
}

export function parseCliJsonResult(
  result: CliSpawnResult,
  args: readonly string[],
): ResultEnvelope<unknown> {
  const lastLine = result.stdout.trim().split("\n").pop() ?? "";
  const warnings = analyzeCliError(result.stderr, args);
  if (lastLine.length > 0) {
    try {
      const parsedJson: unknown = JSON.parse(lastLine);
      const envelope = parseResultEnvelope(parsedJson);
      if (envelope) return envelope;
      logWarn({
        component: "aventure-mcp-server",
        event: "cli_envelope_invalid",
        message: "aventure-cli stdout JSON did not match the result envelope",
        fields: { exitCode: result.exitCode, args: args.join(" ") },
      });
      return failure(`aventure-cli exited ${result.exitCode}`, [
        ...warnings,
        "CLI stdout JSON did not match the result envelope",
      ]);
    } catch (error) {
      logWarn({
        component: "aventure-mcp-server",
        event: "cli_stdout_json_parse_failed",
        message: describeError(error),
        fields: { exitCode: result.exitCode, args: args.join(" ") },
        error,
      });
      return failure(`aventure-cli exited ${result.exitCode}`, [
        ...warnings,
        `CLI stdout JSON parse failed: ${describeError(error)}`,
      ]);
    }
  }
  return failure(`aventure-cli exited ${result.exitCode}`, warnings);
}

/** Map CLI stderr into agent-actionable next steps. Short imperative warnings; no full traces. */
export function analyzeCliError(stderr: string, args: readonly string[]): string[] {
  const warnings: string[] = [];
  if (/CLIENT_SECRET/i.test(stderr)) {
    warnings.push("set CLIENT_SECRET via Doppler");
  }
  if (/ADMIN_API_KEY|AUTH_TOKEN/i.test(stderr)) {
    warnings.push("set ADMIN_API_KEY or AUTH_TOKEN for writes");
  }
  if (/ENOTFOUND|ECONNREFUSED|EAI_AGAIN|socket/i.test(stderr)) {
    warnings.push("API host unreachable — verify network access to the configured API_URL");
  }
  if (/duplicate candidates|duplicate-check/i.test(stderr)) {
    warnings.push("review duplicate candidates before retrying");
  }
  if (warnings.length === 0) {
    warnings.push(stderr.slice(0, 200) || `aventure-cli ${args.join(" ")} failed`);
  }
  return warnings;
}

/**
 * Convert a ResultEnvelope into an MCP CallToolResult.
 *  - Byte-caps the JSON envelope at 50KB to keep the MCP channel terse.
 *  - isError=true when the envelope is ok=false.
 */
export function toCallToolResult(envelope: ResultEnvelope<unknown>): CallToolResult {
  const capped = capEnvelope(envelope);
  const text = asCliResponseText(capped.data, capped.summary) ?? JSON.stringify(capped);
  return {
    isError: !capped.ok,
    structuredContent: { ...capped },
    content: [{ type: "text", text }],
  };
}
